FeatureScript 3083;
import(path : "onshape/std/common.fs", version : "3083.0");

// Generated by fsgen (paste export). Paste into a Feature Studio, then add the feature
// to a Part Studio from the toolbar. Parameters appear in the feature dialog.

// Midpoint of an arc from its endpoints; k = tan(sweep / 4) keeps the arc's sweep when parameters change.
function arcMid(a is Vector, b is Vector, k is number) returns Vector
{
    var d = b - a;
    return (a + b) / 2 + vector(d[1], -d[0]) * (k / 2);
}

annotation { "Feature Type Name" : "Servo pinion" }
export const servoPinion = defineFeature(function(context is Context, id is Id, definition is map)
    precondition
    {
        annotation { "Name" : "Gear width" }
        isLength(definition.gearWidth, { (millimeter) : [0, 12.3, 10000] } as LengthBoundSpec);
        annotation { "Name" : "Outside diameter" }
        isLength(definition.outsideDiameter, { (millimeter) : [0, 20.768, 10000] } as LengthBoundSpec);
        annotation { "Name" : "Spline socket diameter" }
        isLength(definition.splineSocketDiameter, { (millimeter) : [0, 6, 10000] } as LengthBoundSpec);
        annotation { "Name" : "Spline socket depth" }
        isLength(definition.splineSocketDepth, { (millimeter) : [0, 3.5, 10000] } as LengthBoundSpec);
        annotation { "Name" : "Screw hole diameter" }
        isLength(definition.screwHoleDiameter, { (millimeter) : [0, 3.4, 10000] } as LengthBoundSpec);
        annotation { "Name" : "Head recess diameter" }
        isLength(definition.headRecessDiameter, { (millimeter) : [0, 6.94, 10000] } as LengthBoundSpec);
        annotation { "Name" : "Head recess depth" }
        isLength(definition.headRecessDepth, { (millimeter) : [0, 1.77, 10000] } as LengthBoundSpec);
    }
    {
    // Body sketch
    var bodySketchSk = newSketchOnPlane(context, id + "bodySketch", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, -1, 0), vector(1, 0, 0)) });
    skLineSegment(bodySketchSk, "section_0", { "start" : vector(definition.headRecessDiameter / 2, (0 * millimeter)), "end" : vector(definition.outsideDiameter / 2, (0 * millimeter)) });
    skLineSegment(bodySketchSk, "section_1", { "start" : vector(definition.outsideDiameter / 2, (0 * millimeter)), "end" : vector(definition.outsideDiameter / 2, definition.gearWidth) });
    skLineSegment(bodySketchSk, "section_2", { "start" : vector(definition.outsideDiameter / 2, definition.gearWidth), "end" : vector(definition.splineSocketDiameter / 2, definition.gearWidth) });
    skLineSegment(bodySketchSk, "section_3", { "start" : vector(definition.splineSocketDiameter / 2, definition.gearWidth), "end" : vector(definition.splineSocketDiameter / 2, definition.gearWidth - definition.splineSocketDepth) });
    skLineSegment(bodySketchSk, "section_4", { "start" : vector(definition.splineSocketDiameter / 2, definition.gearWidth - definition.splineSocketDepth), "end" : vector(definition.screwHoleDiameter / 2, definition.gearWidth - definition.splineSocketDepth) });
    skLineSegment(bodySketchSk, "section_5", { "start" : vector(definition.screwHoleDiameter / 2, definition.gearWidth - definition.splineSocketDepth), "end" : vector(definition.screwHoleDiameter / 2, definition.headRecessDepth) });
    skLineSegment(bodySketchSk, "section_6", { "start" : vector(definition.screwHoleDiameter / 2, definition.headRecessDepth), "end" : vector(definition.headRecessDiameter / 2 - (definition.headRecessDepth * 0.5773502692), definition.headRecessDepth) });
    skLineSegment(bodySketchSk, "section_7", { "start" : vector(definition.headRecessDiameter / 2 - (definition.headRecessDepth * 0.5773502692), definition.headRecessDepth), "end" : vector(definition.headRecessDiameter / 2, (0 * millimeter)) });
    skLineSegment(bodySketchSk, "axis", { "start" : vector(0, 0) * millimeter, "end" : vector(0, 10) * millimeter, "construction" : true });
    skSolve(bodySketchSk);
    // Body
    opRevolve(context, id + "body" + "tool", { "entities" : qSketchRegion(id + "bodySketch"), "axis" : line(vector(0, 0, 0) * millimeter, vector(0, 0, 1)), "angleForward" : 360 * degree });
    // Tooth gap sketch
    var toothGapSketchSk = newSketchOnPlane(context, id + "toothGapSketch", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skArc(toothGapSketchSk, "flankA2", { "start" : vector(10.88394475, 0.034681343) * millimeter, "mid" : arcMid(vector(10.88394475, 0.034681343) * millimeter, vector(9.062670216, 1.008951073) * millimeter, 0.1130795916), "end" : vector(9.062670216, 1.008951073) * millimeter });
    skArc(toothGapSketchSk, "flankA1", { "start" : vector(9.062670216, 1.008951073) * millimeter, "mid" : arcMid(vector(9.062670216, 1.008951073) * millimeter, vector(8.469171924, 1.082301302) * millimeter, 0.07647476567), "end" : vector(8.469171924, 1.082301302) * millimeter });
    skLineSegment(toothGapSketchSk, "radialA", { "start" : vector(8.469171924, 1.082301302) * millimeter, "end" : vector(8.003647582, 1.022810527) * millimeter });
    skArc(toothGapSketchSk, "filletA", { "start" : vector(8.003647582, 1.022810527) * millimeter, "mid" : arcMid(vector(8.003647582, 1.022810527) * millimeter, vector(7.449169501, 1.424842356) * millimeter, -0.3962008611), "end" : vector(7.449169501, 1.424842356) * millimeter });
    skArc(toothGapSketchSk, "rootLand", { "start" : vector(7.449169501, 1.424842356) * millimeter, "mid" : arcMid(vector(7.449169501, 1.424842356) * millimeter, vector(7.329685741, 1.948334912) * millimeter, 0.01770531407), "end" : vector(7.329685741, 1.948334912) * millimeter });
    skArc(toothGapSketchSk, "filletB", { "start" : vector(7.329685741, 1.948334912) * millimeter, "mid" : arcMid(vector(7.329685741, 1.948334912) * millimeter, vector(7.654818157, 2.551132097) * millimeter, -0.3962008613), "end" : vector(7.654818157, 2.551132097) * millimeter });
    skLineSegment(toothGapSketchSk, "radialB", { "start" : vector(7.654818157, 2.551132097) * millimeter, "end" : vector(8.100053176, 2.699516203) * millimeter });
    skArc(toothGapSketchSk, "flankB1", { "start" : vector(8.100053176, 2.699516203) * millimeter, "mid" : arcMid(vector(8.100053176, 2.699516203) * millimeter, vector(8.602951188, 3.023111734) * millimeter, 0.07647476905), "end" : vector(8.602951188, 3.023111734) * millimeter });
    skArc(toothGapSketchSk, "flankB2", { "start" : vector(8.602951188, 3.023111734) * millimeter, "mid" : arcMid(vector(8.602951188, 3.023111734) * millimeter, vector(9.821143046, 4.691119832) * millimeter, 0.1130795922), "end" : vector(9.821143046, 4.691119832) * millimeter });
    skLineSegment(toothGapSketchSk, "outside", { "start" : vector(9.821143046, 4.691119832) * millimeter, "end" : vector(10.88394475, 0.034681343) * millimeter });
    skSolve(toothGapSketchSk);
    // Tooth gap
    opExtrude(context, id + "toothGap" + "tool", { "entities" : qSketchRegion(id + "toothGapSketch"), "direction" : vector(0, 0, 1), "endBound" : BoundingType.THROUGH_ALL });
    opBoolean(context, id + "toothGap" + "bool", { "tools" : qCreatedBy(id + "toothGap" + "tool", EntityType.BODY), "targets" : qSubtraction(qBodyType(qCreatedBy(id, EntityType.BODY), BodyType.SOLID), qCreatedBy(id + "toothGap" + "tool", EntityType.BODY)), "operationType" : BooleanOperationType.SUBTRACTION });
    // Gear teeth
    for (var k0_0_0 = 1; k0_0_0 < 14; k0_0_0 += 1)
    {
        opExtrude(context, id + "gearTeeth" + ("0_0_" ~ k0_0_0) + "tool", { "entities" : qSketchRegion(id + "toothGapSketch"), "direction" : vector(0, 0, 1), "endBound" : BoundingType.THROUGH_ALL });
        opTransform(context, id + "gearTeeth" + ("0_0_" ~ k0_0_0) + "move", { "bodies" : qCreatedBy(id + "gearTeeth" + ("0_0_" ~ k0_0_0) + "tool", EntityType.BODY), "transform" : rotationAround(line(vector(0, 0, 0) * millimeter, vector(0, 0, 1)), k0_0_0 * ((360 * degree)) / (14)) });
        opBoolean(context, id + "gearTeeth" + ("0_0_" ~ k0_0_0) + "bool", { "tools" : qCreatedBy(id + "gearTeeth" + ("0_0_" ~ k0_0_0) + "tool", EntityType.BODY), "targets" : qSubtraction(qBodyType(qCreatedBy(id, EntityType.BODY), BodyType.SOLID), qCreatedBy(id + "gearTeeth" + ("0_0_" ~ k0_0_0) + "tool", EntityType.BODY)), "operationType" : BooleanOperationType.SUBTRACTION });
    }
    // remove the construction sketches and curves
    opDeleteBodies(context, id + "cleanupSketches", { "entities" : qUnion([qCreatedBy(id + "bodySketch", EntityType.BODY), qCreatedBy(id + "toothGapSketch", EntityType.BODY)]) });
    });
